<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); $secondary = is_array( $section_data['secondary_items'] ?? null ) ? $section_data['secondary_items'] : array(); ?>
<section class="guarantees guarantees--<?php echo esc_attr( $mode ); ?>" id="<?php echo esc_attr( $root_id ); ?>" data-guarantees aria-labelledby="<?php echo esc_attr( $title_id ); ?>"><div class="container">
  <header class="guarantees__header"><?php if ( ! empty( $section_data['eyebrow'] ) ) : ?><span class="guarantees__badge"><?php echo esc_html( $section_data['eyebrow'] ); ?></span><?php endif; ?><h2 class="guarantees__title" id="<?php echo esc_attr( $title_id ); ?>"><?php echo esc_html( $section_data['title'] ?? '' ); ?><?php if ( ! empty( $section_data['title_accent'] ) ) : ?> <span><?php echo esc_html( $section_data['title_accent'] ); ?></span><?php endif; ?></h2><div class="guarantees__description"><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div></header>
  <div class="guarantees__cards"><?php foreach ( $items as $item ) : ?><article class="guarantee-card"><div><h3><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php if ( ! empty( $item['value'] ) ) : ?><strong><?php echo esc_html( $item['value'] ); ?></strong><?php endif; ?></div><?php echo platejka_section_image( $item['image'] ?? 0, 'large', array( 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></article><?php endforeach; ?><div class="guarantees__slider" data-guarantees-slider tabindex="0"><?php foreach ( $secondary as $item ) : ?><article class="guarantee-card"><h3><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php echo platejka_section_image( $item['image'] ?? 0, 'medium', array( 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></article><?php endforeach; ?></div></div>
</div></section>
